 {"clause_id": "c007",
  "issues": [
   {"issue": null, "type": 1, "prob": 0.12},
   {"issue": "\"Earning well\" is defined but appears nowhere in the operative text, which instead uses \"farmout well\" and \"well capable of production in paying quantities\". An unused definition invites argument about which wells it was meant to capture.", "type": 2, "prob": 0.18}
