 {"clause_id": "c012",
  "issues": [
   {"issue": "The definition turns on capability of producing in \"commercial quantities\", a term used nowhere else and undefined, while the rest of the Agreement measures wells by \"paying quantities\". Which standard applies to a shut-in well is open.", "type": 1, "prob": 0.30},
   {"issue": "This definition requires that the well \"has previously produced\", but Section 7(A) imposes the shut-in royalty on any capable well \"whether or not such well has already produced\". The two cannot both describe the class of shut-in wells.", "type": 2, "prob": 0.38}
  ]},
 {"clause_id": "c013",
  "issues": [
