  ]},
 {"clause_id": "c015",
  "issues": [
   {"issue": "\"Payout\" compares \"gross proceeds attributable to the sale or production from a well\" to \"the cost of drilling, completing and equipping\" it, without saying whose costs, whether operating costs count, or what \"proceeds attributable to ... production\" (as opposed to sale) means. Each of those is a live construction question.", "type": 1, "prob": 0.36},
