  ]},
 {"clause_id": "c018",
  "issues": [
   {"issue": null, "type": 1, "prob": 0.07},
   {"issue": "This subsection requires only that Farmee \"commence the actual drilling\" by August 31, 1996, whereas Section 16 conditions the Right of First Refusal on Farmee having \"drill[ed] and complete[d] the test well on or before August 31, 1996\". The two dates cannot both be met on the schedule Section 3(A)(3) allows.", "type": 2, "prob": 0.32}
  ]},
 {"clause_id": "c019",
  "issues": [
   {"issue": "The deadline is stated as a fragment with no verb — it fixes a period but never says what must occur within it or by whom. Whether \"completion\" means the Section 2(A) \"completed well\" standard has to be supplied by construction.", "type": 1, "prob": 0.24},
   {"issue": null, "type": 2, "prob": 0.12}
  ]},
 {"clause_id": "c020",
  "issues": [
   {"issue": null, "type": 1, "prob": 0.16},
   {"issue": "This subsection makes subsequent drilling an \"option\" of Farmee, but Section 3(B)(3) says Farmee \"must commence the actual drilling of two (2) Subsequent Wells\" by December 31, 1996, and Section 13(A) treats failure under 3(B)(3) as a terminating breach of \"drilling commitments\". Whether subsequent wells are optional or obligatory is squarely in issue.", "type": 2, "prob": 0.50}
